/***************************************************************************************************** 
 *
 * We are given a linked list with head as the first node.  Let's number the nodes in the list: 
 * node_1, node_2, node_3, ... etc.
 * 
 * Each node may have a next larger value: for node_i, next_larger(node_i) is the node_j.val such that 
 * j > i, node_j.val > node_i.val, and j is the smallest possible choice.  If such a j does not exist, 
 * the next larger value is 0.
 * 
 * Return an array of integers answer, where answer[i] = next_larger(node_{i+1}).
 * 
 * Note that in the example inputs (not outputs) below, arrays such as [2,1,5] represent the 
 * serialization of a linked list with a head node value of 2, second node value of 1, and third node 
 * value of 5.
 * 
 * Example 1:
 * 
 * Input: [2,1,5]
 * Output: [5,5,0]
 * 
 * Example 2:
 * 
 * Input: [2,7,4,3,5]
 * Output: [7,0,5,5,0]
 * 
 * Example 3:
 * 
 * Input: [1,7,5,1,9,2,5,1]
 * Output: [7,9,9,9,0,5,0,0]
 * 
 * Note:
 * 
 * 	1 <= node.val <= 10^9 for each node in the linked list.
 * 	The given list has length in the range [0, 10000].
 * 
 ******************************************************************************************************/

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public int[] nextLargerNodes(ListNode head) {
        var list = new ArrayList<Integer>();
        while (head != null) {
            list.add(head.val);
            head = head.next;
        }

        // 单调递减栈
        var stack = new Stack<Integer>();
        var result = new int[list.size()];

        for (var i = 0; i < list.size(); i++) {
            if (stack.isEmpty()) {
                stack.push(i);
            } else if (list.get(stack.peek()) >= list.get(i)) {
                stack.push(i);
            } else {
                result[stack.pop()] = list.get(i);
                i--;
            }
        }

        // 栈里剩下的元素不用处理了，因为结果是 0，result 数组默认值就是 0

        return result;
    }
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<int> nextLargerNodes(ListNode* head) {
        vector<int> values;
        while (head != nullptr) {
            values.push_back(head->val);
            head = head->next;
        }

        int n = int(values.size());
        stack<int> iStack;
        vector<int> answer(n);

        for (int i = 0; i < n; ++i) {
            while (!iStack.empty() && values[iStack.top()] < values[i]) {
                int smaller = iStack.top();
                iStack.pop();
                answer[smaller] = values[i];
            }
            iStack.push(i);
        }

        return answer;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<int> nextLargerNodes(ListNode* head) {
        vector<int> answer;
        vector<pair<int, int>> stk;
        // We use an integer 'cnt' to represent the index.
        int cnt = 0;

        while(head != nullptr){
            // Set the next greate value of the current value 'head.val' as 0 by default.
            answer.push_back(0);
            while(stk.size() && head->val > stk.back().second){
                auto [id, val] = stk.back();
                stk.pop_back();
                answer[id] = head->val;
            }
            // Add both the index and the value to stack.
            stk.push_back({cnt++, head->val});
            head = head->next;
        }
        return answer;
    }
};

/**
